import ipaddress,struct,pathlib,os,tempfile

def checksum(data):
    if len(data)%2:data+=b'\x00'
    value=sum(struct.unpack('!%dH'%(len(data)//2),data))
    while value>>16:value=(value&65535)+(value>>16)
    return (~value)&65535

def build(packet,router,mtu):
    if not isinstance(packet,bytes) or len(packet)<48 or len(packet)>65575:raise ValueError('packet size')
    if packet[0]>>4!=6 or packet[6]!=17:raise ValueError('plain IPv6 UDP required')
    length=int.from_bytes(packet[4:6],'big')
    if length<8 or len(packet)!=40+length or int.from_bytes(packet[44:46],'big')!=length:raise ValueError('length mismatch')
    source=ipaddress.IPv6Address(packet[8:24]);destination=ipaddress.IPv6Address(packet[24:40])
    if source.is_multicast or source.is_unspecified:raise ValueError('unreplyable source')
    if not isinstance(router,str):raise ValueError('router text required')
    try:reply_source=ipaddress.IPv6Address(router)
    except ipaddress.AddressValueError as error:raise ValueError('router IPv6') from error
    if '%' in router or reply_source.is_multicast or reply_source.is_unspecified:raise ValueError('router unicast')
    if type(mtu) is not int or mtu<1280 or mtu>=len(packet):raise ValueError('not over configured IPv6 link MTU')
    pseudo=source.packed+destination.packed+struct.pack('!I3xB',length,17)
    if packet[46:48]==b'\x00\x00' or checksum(pseudo+packet[40:])!=0:raise ValueError('UDP checksum')
    message=struct.pack('!BBHI',2,0,0,mtu)+packet[:1232]
    pseudo=reply_source.packed+source.packed+struct.pack('!I3xB',len(message),58)
    message=message[:2]+struct.pack('!H',checksum(pseudo+message))+message[4:]
    return struct.pack('!IHBB',6<<28,len(message),58,64)+reply_source.packed+source.packed+message

def publish(router,mtu):
    source=pathlib.Path('offending.hex');target=pathlib.Path('ptb.hex')
    if source.is_symlink() or target.is_symlink() or (target.exists() and not target.is_file()):raise ValueError('regular artifacts')
    if source.stat().st_size>140000:raise ValueError('input too large')
    packet=bytes.fromhex(source.read_text(encoding='ascii'));response=build(packet,router,mtu)
    with tempfile.NamedTemporaryFile('w',dir='.',delete=False,encoding='ascii') as handle:
        name=handle.name;handle.write(response.hex()+'\n');handle.flush();os.fsync(handle.fileno())
    try:os.replace(name,target)
    finally:
        if os.path.exists(name):os.unlink(name)
    return response
