import pathlib,sys,struct,ipaddress,secrets
sys.path.insert(0,str(pathlib.Path.cwd()));import ptb

def valid_sum(data):
    words=[int.from_bytes(data[i:i+2].ljust(2,b'\x00'),'big') for i in range(0,len(data),2)]
    value=sum(words)
    while value>65535:value=(value&65535)+(value>>16)
    return value

def packet(size,src='2001:db8:1::2',dst='2001:db8:2::3'):
    source=ipaddress.IPv6Address(src).packed;destination=ipaddress.IPv6Address(dst).packed
    length=size-40;udp=struct.pack('!HHHH',40000+secrets.randbelow(1000),9000,length,0)+secrets.token_bytes(length-8)
    pseudo=source+destination+struct.pack('!I3xB',length,17)
    check=65535-valid_sum(pseudo+udp)
    udp=udp[:6]+struct.pack('!H',check or 65535)+udp[8:]
    return struct.pack('!IHBB',6<<28,length,17,63)+source+destination+udp

def verify(raw,router,mtu):
    saved=bytes(raw);result=ptb.build(raw,router,mtu)
    assert raw==saved and isinstance(result,bytes)
    assert len(result)==1280 and result[:4]==bytes.fromhex('60000000')
    assert result[6:8]==bytes([58,64]) and int.from_bytes(result[4:6],'big')==1240
    assert result[8:24]==ipaddress.IPv6Address(router).packed and result[24:40]==raw[8:24]
    assert result[40:42]==bytes([2,0]) and int.from_bytes(result[44:48],'big')==mtu
    assert result[48:]==raw[:1232], 'quote must preserve invoking bytes and cap at 1232'
    pseudo=result[8:40]+struct.pack('!I3xB',len(result)-40,58)
    assert valid_sum(pseudo+result[40:])==65535, 'ICMPv6 pseudo-header checksum invalid'
    return result
